import React from 'react';
import UsersTable from '../Pages/Users/UsersTable';
import { Plus } from 'lucide-react';

const UsersPage = () => {
  return (
    <>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-neutral-900 dark:text-white">Gestion des utilisateurs</h1>
          <p className="text-neutral-600 dark:text-neutral-400">Gérez tous les utilisateurs de votre plateforme</p>
        </div>
        <button className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:from-primary-600 hover:to-secondary-600 transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/25">
          <Plus className="h-5 w-5" />
          <span>Ajouter un utilisateur</span>
        </button>
      </div>

      <UsersTable />
    </>
  );
};

export default UsersPage;
